const input = $input.first()?.json?.body || {};
const evidence = input.evidence || [];

// 8 Contradiction Detection Patterns
const patterns = [
  { id: 'P1', name: 'Problem-Signal Reversal', description: 'Customers describe the problem but show low urgency scores', severity: 'medium' },
  { id: 'P2', name: 'Channel-Conversion Mismatch', description: 'High channel reach but low conversion rate — ICP misalignment', severity: 'medium' },
  { id: 'P3', name: 'Pricing-Willingness Gap', description: 'Product loved but pricing rejected — model-market misalignment', severity: 'high' },
  { id: 'P4', name: 'Pilot-Pipeline Divergence', description: 'Pilots succeed but pipeline stalls — channel misses pilot-quality prospects', severity: 'high' },
  { id: 'P5', name: 'ICP Drift', description: 'Closed deals diverge from defined ICP — model needs recalibration', severity: 'high' },
  { id: 'P6', name: 'Advocacy-Retention Contradiction', description: 'High NPS but churning customers — measurement lag or wrong segment', severity: 'medium' },
  { id: 'P7', name: 'Community-Commercial Gap', description: 'Strong community engagement but no commercial traction', severity: 'medium' },
  { id: 'P8', name: 'Confidence-Evidence Asymmetry', description: 'High-confidence scores built on low-reliability evidence sources', severity: 'medium' }
];

const now = new Date().toISOString();

if (evidence.length === 0) {
  return [{ json: {
    mode: 'pattern_reference',
    message: 'No evidence provided — returning pattern definitions for inspection',
    patterns: patterns,
    contradictions: [],
    run_at: now
  } }];
}

// Simple heuristic detection against evidence array
const detected = [];
for (const p of patterns) {
  const relevantEvidence = evidence.filter(e => e.direction && e.magnitude !== undefined);
  const conflicts = relevantEvidence.filter(e => e.confidence > 0.7 && e.source_reliability < 0.5);

  if ((p.id === 'P8' && conflicts.length >= 2) ||
      (p.id !== 'P8' && relevantEvidence.some(e => e.direction === 'negative' && e.magnitude > 0.6))) {
    detected.push({
      ...p,
      detected_at: now,
      supporting_evidence_count: relevantEvidence.length,
      status: 'new',
      llm_prompt: 'Analyze contradiction: ' + p.name + ' — ' + p.description + ' for GuardSpine GTM. Return JSON: {"root_cause":"string","confirmation_evidence":[],"recommended_experiment":"string","urgency":"high|medium|low"}'
    });
  }
}

return [{ json: { contradictions: detected, evidence_analyzed: evidence.length, run_at: now } }];

const input = $input.first().json;
const contradictions = input.contradictions || [];

if (contradictions.length === 0) {
  return [{ json: { message: 'No contradictions detected this period', count: 0, items: [] } }];
}

return contradictions.map(c => ({ json: c }));

const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json;
  let llmAnalysis = {};
  try {
    const content = data.choices?.[0]?.message?.content || '{}';
    llmAnalysis = typeof content === 'string' ? JSON.parse(content) : content;
  } catch(e) {
    llmAnalysis = { root_cause: 'Analysis pending', urgency: 'medium' };
  }

  output.push({ json: {
    pattern_id: data.pattern_id || data.id,
    pattern_name: data.pattern_name || data.name,
    description: data.description,
    severity: data.severity,
    detected_at: data.detected_at,
    root_cause: llmAnalysis.root_cause || 'Pending',
    confirmation_evidence_needed: llmAnalysis.confirmation_evidence || [],
    recommended_experiment: llmAnalysis.recommended_experiment || '',
    urgency: llmAnalysis.urgency || data.severity,
    status: 'new',
    ready_for_db: true
  } });
}

return output.length > 0 ? output : [{ json: { message: 'No contradictions processed', count: 0 } }];

